SELECT post.id AS "post.id", post.user_id AS "post.user_id", post.created_at AS "post.created_at", post.updated_at AS "post.updated_at", post.title AS "post.title", post.content AS "post.content", author.id AS "author.id", author.created_at AS "author.created_at", author.updated_at AS "author.updated_at", author.address AS "author.address", author.birthday AS "author.birthday", author.email AS "author.email", author.email_verified AS "author.email_verified", author.first_name AS "author.first_name", author.gender AS "author.gender", author.last_name AS "author.last_name" FROM posts AS post JOIN users AS author ON author.id = post.user_id WHERE post.id = $1;
